import numpy as np


def shift_images(X, dx, dy):
    X = np.asarray(X, dtype=float)
    out = np.zeros_like(X)
    h, w = X.shape[-2], X.shape[-1]
    for i in range(h):
        for j in range(w):
            if 0 <= i - dy < h and 0 <= j - dx < w:
                out[..., i - dy, j - dx] = X[..., i, j]
    return out
